/** IBM VGA 8×16 bitmap (Linux kernel font_8x16 — GPL-2.0, baked as 1:1 atlas pixels). */

const FONT_B64 = '';

/** @type {Uint8Array | null} */
let vgaFontBytes = null;

/** @returns {Uint8Array} 256 glyphs × 16 row bytes */
export function getVga8x16FontBytes() {
  if (!vgaFontBytes) {
    const bin = atob(FONT_B64);
    vgaFontBytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i += 1) {
      vgaFontBytes[i] = bin.charCodeAt(i);
    }
  }
  return vgaFontBytes;
}

/**
 * Blit one 8×16 glyph to a 2D canvas (hard on/off pixels).
 * @param {CanvasRenderingContext2D} ctx
 * @param {string} ch
 * @param {number} destX
 * @param {number} destY
 * @param {number} [scale=1] — nearest-neighbor integer upscale per pixel
 */
export function blitVga8x16Glyph(ctx, ch, destX, destY, scale = 1) {
  const code = ch.charCodeAt(0);
  if (code < 0 || code > 255) return;
  const s = Math.max(1, Math.floor(scale));
  const font = getVga8x16FontBytes();
  const offset = code * 16;
  const outW = 8 * s;
  const outH = 16 * s;
  const img = ctx.createImageData(outW, outH);
  const d = img.data;
  for (let row = 0; row < 16; row += 1) {
    const byte = font[offset + row] ?? 0;
    for (let col = 0; col < 8; col += 1) {
      const on = (byte >> (7 - col)) & 1;
      const v = on ? 255 : 0;
      for (let dy = 0; dy < s; dy += 1) {
        for (let dx = 0; dx < s; dx += 1) {
          const rr = row * s + dy;
          const cc = col * s + dx;
          const i = (rr * outW + cc) * 4;
          d[i] = v;
          d[i + 1] = v;
          d[i + 2] = v;
          d[i + 3] = 255;
        }
      }
    }
  }
  ctx.putImageData(img, destX, destY);
}

/**
 * Blit 8×16 VGA into a target pixel rect (nearest-neighbor fit).
 * @param {CanvasRenderingContext2D} ctx
 * @param {string} ch
 * @param {number} destX
 * @param {number} destY
 * @param {number} destW
 * @param {number} destH
 */
export function blitVga8x16GlyphFit(ctx, ch, destX, destY, destW, destH) {
  const code = ch.charCodeAt(0);
  if (code < 0 || code > 255) return;
  const outW = Math.max(1, Math.floor(destW));
  const outH = Math.max(1, Math.floor(destH));
  const font = getVga8x16FontBytes();
  const offset = code * 16;
  const img = ctx.createImageData(outW, outH);
  const d = img.data;

  for (let py = 0; py < outH; py += 1) {
    const srcRow = Math.min(15, Math.floor((py * 16) / outH));
    const byte = font[offset + srcRow] ?? 0;
    for (let px = 0; px < outW; px += 1) {
      const srcCol = Math.min(7, Math.floor((px * 8) / outW));
      const on = (byte >> (7 - srcCol)) & 1;
      const v = on ? 255 : 0;
      const i = (py * outW + px) * 4;
      d[i] = v;
      d[i + 1] = v;
      d[i + 2] = v;
      d[i + 3] = 255;
    }
  }
  ctx.putImageData(img, destX, destY);
}
